import {
    SCROLLING_MODE_INFINITE,
    SCROLLING_MODE_VIRTUAL
} from "../const";
export const isVirtualMode = that => that.option("scrolling.mode") === SCROLLING_MODE_VIRTUAL;
export const isInfiniteMode = that => that.option("scrolling.mode") === SCROLLING_MODE_INFINITE;
export const isVirtualPaging = that => isVirtualMode(that) || isInfiniteMode(that);
